"""Emit a byte-complete classification contract, not an exporter/default generator."""
import argparse,csv,json
from pathlib import Path
p=argparse.ArgumentParser();p.add_argument('--output',type=Path,required=True);a=p.parse_args()
rows=[]
def row(first,last,field,policy,evidence,condition):rows.append(dict(first=f'{first:03X}',last=f'{last:03X}',bytes=last-first+1,field=field,policy=policy,evidence=evidence,condition=condition))
row(0,10,'nation name','LIVE_OR_VERIFIED_CLASSIC','DAT loader4481A0; ShowNationStatus43BA7C','11-byte ANSI/NUL buffer; supported ASCII max10; fixed classic identity must match DAT')
row(11,37,'leader name','LIVE','NewGame448AA4; new leader449078','27-byte ANSI/NUL buffer max26; names after NUL are residue, not another field')
row(38,69,'diplomacy row','LIVE','449B40; Politics452C9C..453230','16 signed WORDs including negative cooldown; missing cooldown cannot silently become peace')
row(70,71,'neighbour mask','VERIFIED_CLASSIC','DAT4481A0; peace450C68; offer452034','Use exact pinned original scenario mask; not inferred from current city ownership')
row(72,739,'owned-city IDs,334 WORDs','DERIVE_WITH_PROFILE','44B8F4; FindCity43D93C; recruitment4502E0; public224; x86city','Rebuild active owned IDs in original name order; -1 inactive invariant from DAT/transfer; validate count and ownership')
row(740,1059,'recruit queues,40x8','LIVE_AND_RESIDUE','44A4E0;44A610;4504F4','Active state/type/troops/city must map exactly; troop=0 logical emptiness does not mean all other bytes zero')
row(1060,1071,'three nation colours','VERIFIED_CLASSIC_OR_PRESERVE_UI','NewGame448AA4; recolour44A6C8','3 DWORD colour values initialized explicitly per nation; no unit pointer or score')
row(1072,1075,'current population/wealth','LIVE','quarter451B40; ownership44BED8','Map exact original units/tick semantics; not an arbitrary template constant')
row(1076,1079,'270BC population baseline','HISTORICAL_PROFILE_OR_LIVE_HISTORY','DAT4481A0; HumanFalls455E38 lines56436-56437; DAT224','Use attested original270BC history/DAT baseline; do NOT overwrite from current population')
row(1080,1083,'current treasury','LIVE','quarter451B40; recruit4504F4','Signed DWORD; may legitimately be negative')
row(1084,1087,'270BC treasury baseline','HISTORICAL_PROFILE_OR_LIVE_HISTORY','DAT4481A0; HumanFalls455E38 lines56447-56448; DAT224','Same history requirement; not current treasury or zero')
row(1088,1089,'unity','LIVE','44C8F0;451B40','Current original scalar and defeated-state interpretation')
row(1090,1091,'mobilization','LIVE','4504F4;451B40','Current percentage; do not reset to NewGame level')
row(1092,1093,'capital city ID','LIVE_OR_DERIVE_PROVEN','44C360;44B8D0','Native stable city identity -> original city index; -1 only supported eliminated state')
row(1094,1095,'current owned city count','DERIVE','44BED8;44B8F4','Exactly number of cities in owner map/list')
row(1096,1097,'270BC city-count baseline','HISTORICAL_PROFILE_OR_LIVE_HISTORY','DAT4481A0; HumanFalls455E38 lines56441-56442; DAT224','Not current count; pinned history or reject')
row(1098,1099,'tax rate','LIVE','quarter451B40; TChangeTax_OK4540B8','Original signed WORD percent; must map native taxation semantics')
row(1100,1101,'tax-base/economy aggregate','LIVE_OR_DERIVE_PROVEN','451B40;4498B0;44BED8','Exact original aggregate/tick/transfer semantics, not a name-based wealth guess')
row(1102,1103,'conqueror nation','LIVE_HISTORY','44BED8;44C360;44C528;HumanFalls455E38','Valid nation0..15 or original -1 sentinel; lost history rejects instead of unrelated-template value')
row(1104,1130,'unnamed27 bytes','UNKNOWN_REJECT_CHANGED_STATE','DAT/NewGame do not initialize explicitly; targeted source inventory; public224allzero','Meaning not proved. Observed zero is NOT a canonical default. Preserve only unchanged identity state; same-template provenance alone does not justify changed-state inheritance')
row(1131,1131,'hints preference','PRESERVE_VALIDATED_UI_OR_CANONICAL','NewGame448AA4; StartTurn45AC5C; ToggleHints45C294','BYTE bool; original new-game1; changes toolbar/hints')
row(1132,1132,'area-map display toggle','PRESERVE_VALIDATED_UI_OR_CANONICAL','NewGame448AA4; AreaMap43DFD4','BYTE bool; original new-game1; paint-mode preference')
row(1133,1133,'unnamed byte','UNKNOWN_REJECT_CHANGED_STATE','public224zero; no meaning established','No zero-fill blessing; unchanged identity only, changed gameplay rejects until semantic proof')
row(1134,1141,'area-window geometry','PRESERVE_VALIDATED_UI','NewGame448AA4; StoreFormPositions45BB1C','Four signed WORDs left/top/height/width; profile must fit runtime, not native gameplay')
row(1142,1149,'unit-window geometry','PRESERVE_VALIDATED_UI','NewGame448AA4; StoreFormPositions45BB1C','Four signed WORDs left/top/height/width; not saved object pointers')
row(1150,1157,'information-window geometry','PRESERVE_VALIDATED_UI','NewGame448AA4; Info43B014; StoreFormPositions45BB1C','Four signed WORDs left/top/height/width; load may round height down modulo16')
row(1158,1159,'unit-map viewport Y','PRESERVE_BOUNDED_UI','448AA4; UnitMapPaint445D38','WORD original new-game45; ensure valid map bounds')
row(1160,1161,'unit-map viewport X','PRESERVE_BOUNDED_UI','448AA4; UnitMapPaint445D38','WORD original new-game55; ensure valid map bounds')
row(1162,1163,'selected nation/map filter','PRESERVE_VALIDATED_UI','NewGame448AA4; SelectNation45B660; AreaMap','WORD0..15 or16 all; NewGame own nation index')
row(1164,1165,'battle melee delay','PRESERVE_VALIDATED_TIMING','BattleDelays436B64;393EC;NewGame448AA4','WORD default30, UI bounds0..30; timing preference not current controller')
row(1166,1167,'battle shooting delay','PRESERVE_VALIDATED_TIMING','BattleDelays436B64;3910C;NewGame448AA4','WORD default20, UI bounds0..30; no future-RNG claim')
row(1168,1168,'human controller','LIVE','449050;451FDC;452034;37DE4','BYTE bool must match intended native controller mask; cannot copy arbitrary-template humans')
row(1169,1171,'unnamed3 bytes','UNKNOWN_REJECT_CHANGED_STATE','public224zero; no meaning established','Meaning not proved; unchanged identity only, changed gameplay rejects, not implicit zero')
covered=[]
for r in rows:covered.extend(range(int(r['first'],16),int(r['last'],16)+1))
assert covered==list(range(1172))
assert sum(r['bytes'] for r in rows if r['policy'].startswith('UNKNOWN'))==31
with a.output.open('x',newline='') as out:
 w=csv.DictWriter(out,fieldnames=list(rows[0]));w.writeheader();w.writerows(rows)
print(json.dumps(dict(regions=len(rows),bytes=len(covered),unknown_bytes=31)))
